import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";
import { layerManager, type Layer } from "./layers";

export function useControllable<T>(props: Record<string, any>, key: string, emit: (...args: any[]) => void, fallback: T) {
  const local = ref<T>(fallback) as Ref<T>;
  const read = () => props[key] as T | undefined;
  return computed<T>({
    get() { const supplied = read(); return supplied === undefined ? local.value : supplied; },
    set(value) { if (read() === undefined) local.value = value; emit(`update:${key}`, value); },
  });
}

export function useMediaQuery(query: string) {
  const matches = ref(false);
  let disconnect: (() => void) | undefined;
  onMounted(() => {
    if (typeof window.matchMedia !== "function") return;
    const media = window.matchMedia(query);
    const update = () => { matches.value = media.matches; };
    update();
    media.addEventListener?.("change", update);
    disconnect = () => media.removeEventListener?.("change", update);
  });
  onBeforeUnmount(() => disconnect?.());
  return matches;
}
export function useReducedMotion() { return useMediaQuery("(prefers-reduced-motion: reduce)"); }

const lockedProperties = ["overflow", "position", "top", "left", "right", "width"] as const;
let scrollOwners = 0;
let unlockPage: (() => void) | undefined;
function acquirePage() {
  if (scrollOwners++ === 0) {
    const body = document.body.style;
    const saved = lockedProperties.map(name => ({ name, value: body.getPropertyValue(name), priority: body.getPropertyPriority(name) }));
    const x = window.scrollX, y = window.scrollY;
    body.setProperty("overflow", "hidden");
    body.setProperty("position", "fixed");
    body.setProperty("left", `${-x}px`);
    body.setProperty("top", `${-y}px`);
    body.setProperty("right", "0px");
    body.setProperty("width", "100%");
    unlockPage = () => {
      for (const entry of saved) {
        if (entry.value) body.setProperty(entry.name, entry.value, entry.priority);
        else body.removeProperty(entry.name);
      }
      const root = document.documentElement.style;
      const behavior = root.getPropertyValue("scroll-behavior");
      const priority = root.getPropertyPriority("scroll-behavior");
      root.setProperty("scroll-behavior", "auto");
      window.scrollTo(x, y);
      if (behavior) root.setProperty("scroll-behavior", behavior, priority);
      else root.removeProperty("scroll-behavior");
    };
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--scrollOwners === 0) { unlockPage?.(); unlockPage = undefined; }
  };
}
export function useScrollLock(locked: Ref<boolean>) {
  let mounted = false;
  let release: (() => void) | undefined;
  const update = (value: boolean) => {
    if (!mounted) return;
    if (value && !release) release = acquirePage();
    if (!value && release) { release(); release = undefined; }
  };
  onMounted(() => { mounted = true; update(locked.value); });
  watch(locked, update);
  onBeforeUnmount(() => { release?.(); release = undefined; mounted = false; });
}

export function resolveElement<T extends Element = HTMLElement>(value: unknown): T | null {
  if (!value) return null;
  const unwrapped = (value as { $el?: unknown }).$el ?? value;
  return typeof (unwrapped as Element).nodeType === "number" && (unwrapped as Element).nodeType === 1 ? unwrapped as T : null;
}
const focusable = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function createLayer(modal: boolean, panel?: { readonly value: unknown }): Layer {
  return { key: Symbol("orvui-layer"), modal, owner: getCurrentInstance(), surface: () => resolveElement(panel?.value), returnTo: null };
}
export function useOverlay(open: Ref<boolean>, panel: Ref<HTMLElement | null>, close: () => void, initialFocus?: () => HTMLElement | undefined) {
  const layer = createLayer(true, panel);
  let mounted = false;
  let revision = 0;
  const sync = async (value: boolean) => {
    const current = ++revision;
    if (!mounted) return;
    if (!value) { layerManager.detach(layer, true); return; }
    if (!layerManager.attach(layer)) return;
    await nextTick();
    if (!mounted || current !== revision || !open.value || !layerManager.top(layer)) return;
    (initialFocus?.() ?? layer.surface()?.querySelector<HTMLElement>(focusable) ?? layer.surface())?.focus({ preventScroll: true });
  };
  const onKey = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !open.value) return;
    if (event.key === "Escape" && layerManager.top(layer)) {
      event.preventDefault(); event.stopPropagation(); close(); return;
    }
    if (event.key !== "Tab" || !layerManager.modal(layer)) return;
    const candidates = new Set<HTMLElement>();
    for (const surface of layerManager.scopes(layer)) {
      for (const node of surface.querySelectorAll<HTMLElement>(focusable)) {
        if (node.getClientRects().length > 0 && !node.closest("[inert]")) candidates.add(node);
      }
    }
    event.preventDefault();
    const nodes = [...candidates];
    if (!nodes.length) { layer.surface()?.focus(); return; }
    const position = nodes.indexOf(document.activeElement as HTMLElement);
    const next = position < 0 ? (event.shiftKey ? nodes.length - 1 : 0) : (position + (event.shiftKey ? -1 : 1) + nodes.length) % nodes.length;
    nodes[next].focus();
  };
  useScrollLock(open);
  onMounted(() => { mounted = true; document.addEventListener("keydown", onKey); void sync(open.value); });
  watch(open, value => void sync(value));
  onBeforeUnmount(() => { mounted = false; revision++; document.removeEventListener("keydown", onKey); layerManager.detach(layer, true); });
  return {
    isTop: () => open.value && layerManager.top(layer),
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
    containsOwnedPortal: (target: HTMLElement) => layerManager.containsPortal(layer.owner, target),
  };
}
export function useFloatingLayer(open: Ref<boolean>, panel?: { readonly value: unknown }) {
  const layer = createLayer(false, panel);
  let mounted = false;
  let unregister: (() => void) | undefined;
  const sync = (value: boolean) => {
    if (!mounted) return;
    if (value) layerManager.attach(layer); else layerManager.detach(layer, false);
  };
  onMounted(() => { mounted = true; unregister = layerManager.portal(layer.owner, layer.surface); sync(open.value); });
  watch(open, sync, { flush: "sync" });
  onBeforeUnmount(() => { mounted = false; unregister?.(); layerManager.detach(layer, false); });
  const isTop = () => open.value && layerManager.top(layer);
  return {
    isTop,
    claimEscape(event: KeyboardEvent) {
      if (event.key !== "Escape" || event.defaultPrevented || !isTop()) return false;
      event.preventDefault(); event.stopImmediatePropagation(); return true;
    },
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
  };
}
export function useEventListener(target: () => EventTarget | null | undefined, event: string, handler: EventListener, options?: AddEventListenerOptions) {
  let remove: (() => void) | undefined;
  onMounted(() => { const element = target(); element?.addEventListener(event, handler, options); remove = () => element?.removeEventListener(event, handler, options); });
  onBeforeUnmount(() => remove?.());
}

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;
export const EASE_OUT_CSS = "cubic-bezier(0.16,1,0.3,1)";
export const SPRING_PRESS = {
  type: "spring",
  stiffness: 500,
  damping: 30,
  mass: 0.6,
} as const;
export const SPRING_SWAP = {
  type: "spring",
  stiffness: 460,
  damping: 30,
  mass: 0.55,
} as const;
export const SPRING_PANEL = {
  type: "spring",
  stiffness: 420,
  damping: 40,
  mass: 0.5,
} as const;
export const SPRING_LAYOUT = {
  type: "spring",
  stiffness: 360,
  damping: 32,
  mass: 0.6,
} as const;
export const SPRING_MOUSE = { stiffness: 200, damping: 15, mass: 0.3 } as const;
export const SPRING_GLIDE = { stiffness: 700, damping: 50, mass: 0.5 } as const;
export const SPRING_TIMELINE = {
  type: "spring",
  stiffness: 120,
  damping: 24,
  mass: 1,
} as const;

// Only ancestry is required; Vue 3.6 parents can also be generic component instances.
type ComponentOwner = { readonly parent: ComponentOwner | null };

type Surface = () => HTMLElement | null;
export interface Layer {
  key: symbol;
  modal: boolean;
  owner: ComponentOwner | null;
  surface: Surface;
  returnTo: HTMLElement | null;
}
const active: Layer[] = [];
const portals = new Set<{ owner: ComponentOwner | null; surface: Surface }>();

function belongsTo(child: ComponentOwner | null, parent: ComponentOwner | null) {
  if (!parent) return false;
  for (let node = child; node; node = node.parent) if (node === parent) return true;
  return false;
}
function later(layer: Layer) {
  const index = active.indexOf(layer);
  return index < 0 ? [] : active.slice(index + 1);
}
export const layerManager = {
  attach(layer: Layer) {
    if (active.includes(layer)) return false;
    layer.returnTo = document.activeElement as HTMLElement | null;
    const before = active.findIndex(entry => entry.owner !== layer.owner && belongsTo(entry.owner, layer.owner));
    active.splice(before < 0 ? active.length : before, 0, layer);
    return true;
  },
  detach(layer: Layer, restore: boolean) {
    const index = active.indexOf(layer);
    if (index < 0) return;
    const wasLast = index === active.length - 1;
    const surface = layer.surface();
    for (const successor of later(layer)) {
      if (successor.returnTo && surface?.contains(successor.returnTo)) successor.returnTo = layer.returnTo;
    }
    active.splice(index, 1);
    if (restore && wasLast && layer.returnTo?.isConnected) layer.returnTo.focus({ preventScroll: true });
  },
  top(layer: Layer) { return active.at(-1) === layer; },
  modal(layer: Layer) { return active.slice().reverse().find(entry => entry.modal) === layer; },
  higher(layer: Layer, target: EventTarget | null) {
    return !!target && typeof (target as Node).nodeType === "number" && later(layer).some(entry => entry.surface()?.contains(target as Node));
  },
  scopes(layer: Layer) {
    const result = [layer.surface()];
    for (const entry of later(layer)) if (!entry.modal && belongsTo(entry.owner, layer.owner)) result.push(entry.surface());
    return result.filter((surface): surface is HTMLElement => surface !== null);
  },
  portal(owner: ComponentOwner | null, surface: Surface) {
    const portal = { owner, surface };
    portals.add(portal);
    return () => portals.delete(portal);
  },
  containsPortal(owner: ComponentOwner | null, target: HTMLElement) {
    for (const portal of portals) {
      const node = portal.surface();
      if (node && belongsTo(portal.owner, owner) && target.contains(node)) return true;
    }
    return false;
  },
};

import { defineComponent, h, isVNode } from "vue";

export default defineComponent({
  props: ["node"],
  setup(props) {
    return () => {
      const content = props.node;
      if (typeof content === "function") return h(content);
      if (content === null || typeof content !== "object" || Array.isArray(content) || isVNode(content)) return content;
      return h(content);
    };
  },
});

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: unknown[]) {
  const combined = clsx(...inputs as ClassValue[]);
  return twMerge(combined);
}
export function clamp(value: number, min: number, max: number) {
  const aboveFloor = Math.max(min, value);
  return Math.min(aboveFloor, max);
}

import { computed, ref, type Ref, type WritableComputedRef } from "vue";

/** A value may move between parent control and local ownership during its life. */
export function useMotionState<T>(
  props: Record<string, any>,
  emit: (...args: any[]) => void,
  key: string,
  fallback: T,
): WritableComputedRef<T> {
  const memory = ref(fallback) as Ref<T>;
  return computed({
    get(): T {
      const supplied = props[key];
      return supplied === undefined ? memory.value : supplied;
    },
    set(requested: T) {
      memory.value = requested;
      emit(`update:${key}`, requested);
      if (key === "modelValue") emit("change", requested);
    },
  });
}

/** Rove focus within the event surface, using its own document. */
export function focusList(event: KeyboardEvent, selector = "button:not(:disabled)") {
  const direction = new Map<string, number>([
    ["ArrowDown", 1], ["ArrowRight", 1], ["ArrowUp", -1], ["ArrowLeft", -1],
  ]).get(event.key);
  if (direction === undefined && event.key !== "Home" && event.key !== "End") return;
  const surface = event.currentTarget as HTMLElement | null;
  if (!surface) return;
  const candidates = [...surface.querySelectorAll<HTMLElement>(selector)];
  if (!candidates.length) return;
  const current = candidates.indexOf(surface.ownerDocument.activeElement as HTMLElement);
  const index = event.key === "Home" ? 0
    : event.key === "End" ? candidates.length - 1
    : current === -1 ? (direction === -1 ? candidates.length - 1 : 0)
    : (current + direction! + candidates.length) % candidates.length;
  event.preventDefault();
  candidates[index]?.focus();
}

import type { VNodeChild } from "vue";

export type SortDirection = "asc" | "desc";

export type SortState = {
  key: string;
  direction: SortDirection;
};

export type TableColumn<T> = {
  /** Stable key; also the default object property read for the cell + sort value. */
  key: string;
  /** Header content. */
  header: VNodeChild;
  /** Allow clicking the header to sort by this column. */
  sortable?: boolean;
  /** Cell text alignment. */
  align?: "left" | "center" | "right";
  /** Column width as a CSS length, e.g. "160px" or "20%". Omit to share remaining space equally. */
  width?: string;
  /** Custom cell renderer. Falls back to `row[key]`. */
  cell?: (row: T) => VNodeChild;
  /** Render an inline text input for this column's cells (ignored when `cell` is set). */
  editable?: boolean;
  /** Value used for sorting. Falls back to `row[key]`. */
  sortValue?: (row: T) => string | number;
};

export type InsertPosition = "before" | "after";

export interface TableProps<T> {
  data: T[];
  columns: TableColumn<T>[];
  /** Stable id per row, required for correct selection across sorts. Defaults to row index. */
  getRowId?: (row: T, index: number) => string;
  /** Render a leading checkbox column with select-all in the header. */
  selectable?: boolean;
  selectedRowIds?: string[];
  defaultSelectedRowIds?: string[];
  onSelectionChange?: (ids: string[]) => void;
  sort?: SortState | null;
  defaultSort?: SortState | null;
  onSortChange?: (sort: SortState | null) => void;
  /** Allow dragging the right edge of a header to resize that column. */
  resizable?: boolean;
  /** Minimum column width in px when resizing. */
  minColumnWidth?: number;
  onColumnResize?: (key: string, width: number) => void;
  /** Allow dragging a header grip to reorder columns. */
  reorderable?: boolean;
  onColumnOrderChange?: (keys: string[]) => void;
  /** Called when an `editable` cell changes. */
  onCellEdit?: (rowId: string, columnKey: string, value: string) => void;
  /** When set, non-sortable headers become editable inputs for the column name. */
  onColumnRename?: (columnKey: string, value: string) => void;
  /** Enables the row menu (Insert before / after). Receives the target index. */
  onInsertRow?: (index: number, position: InsertPosition) => void;
  /** Enables Delete in the row menu. */
  onDeleteRow?: (rowId: string, index: number) => void;
  /** Enables the column menu (Insert before / after). Receives the target column index. */
  onInsertColumn?: (index: number, position: InsertPosition) => void;
  /** Enables Delete in the column menu. */
  onDeleteColumn?: (columnKey: string, index: number) => void;
  /** Fixed row height in px — required for virtualization. */
  rowHeight?: number;
  /** Scroll viewport height in px. */
  height?: number;
  /** Rows rendered above/below the viewport. */
  overscan?: number;
  /** Fires when the viewport scrolls near the bottom — load the next page. */
  onEndReached?: () => void;
  /** Currently fetching — shows skeleton rows and pauses `onEndReached`. */
  loading?: boolean;
  /** How many skeleton rows to show while loading more (default 3). */
  skeletonRows?: number;
  emptyState?: VNodeChild;
  className?: string;
}

/** A data row paired with its stable id. */
export type TableRow<T> = { row: T; id: string };

/** Ref map from column key to its header cell, shared across the resize/reorder hooks. */
export type HeaderCellRefs = {
  current: Record<string, HTMLTableCellElement | null>;
};

import {
  computed,
  nextTick,
  onBeforeUnmount,
  ref,
  useId,
  watch,
  watchEffect,
} from "vue";
import {
  resolveElement,
  useFloatingLayer,
  useReducedMotion,
} from "../../../lib/composables";
export function useTableMenu(changed: (open: boolean) => void) {
  const trigger = ref<HTMLButtonElement | null>(null),
    panel = ref<HTMLElement | null>(null),
    coords = ref<{ top: number; left: number } | null>(null),
    reduce = useReducedMotion(),
    id = useId();
  const layer = useFloatingLayer(
    computed(() => coords.value !== null),
    panel,
  );
  let disposed = false;
  function close(restore = false) {
    coords.value = null;
    if (restore)
      void nextTick(() => {
        if (!disposed) trigger.value?.focus({ preventScroll: true });
      });
  }
  function dismiss() {
    close();
  }
  function escape(event: KeyboardEvent) {
    if (layer.claimEscape(event)) close(true);
  }
  function toggle() {
    if (coords.value) {
      close();
      return;
    }
    const rect = trigger.value?.getBoundingClientRect();
    if (rect)
      coords.value = {
        top: rect.bottom + 4,
        left: Math.max(8, Math.min(innerWidth - 196, rect.right - 188)),
      };
  }
  function navigate(event: KeyboardEvent) {
    if (event.key === "Tab") {
      close();
      return;
    }
    if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    const buttons = Array.from(
        resolveElement<HTMLElement>(
          panel.value,
        )?.querySelectorAll<HTMLButtonElement>("button") ?? [],
      ),
      index = buttons.indexOf(document.activeElement as HTMLButtonElement);
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? buttons.length - 1
          : (index + (event.key === "ArrowDown" ? 1 : -1) + buttons.length) %
            buttons.length;
    buttons[next]?.focus();
  }
  watch(coords, (value) => changed(!!value), { flush: "sync" });
  watchEffect((cleanup) => {
    if (!coords.value) return;
    let active = true;
    window.addEventListener("scroll", dismiss, true);
    window.addEventListener("resize", dismiss);
    window.addEventListener("keydown", escape);
    void nextTick(() => {
      if (active && !disposed)
        resolveElement<HTMLElement>(panel.value)
          ?.querySelector<HTMLButtonElement>("button")
          ?.focus({ preventScroll: true });
    });
    cleanup(() => {
      active = false;
      window.removeEventListener("scroll", dismiss, true);
      window.removeEventListener("resize", dismiss);
      window.removeEventListener("keydown", escape);
    });
  });
  onBeforeUnmount(() => {
    disposed = true;
  });
  return { trigger, panel, coords, reduce, id, close, toggle, navigate };
}

import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useVirtualizer } from "@tanstack/vue-virtual";
import {
  ArrowLeftToLine,
  ArrowRightToLine,
  ArrowUpToLine,
  ArrowDownToLine,
  Trash2,
} from "lucide-vue-next";
import { useMotionState } from "../../state";
import { useReducedMotion } from "../../../lib/composables";
import { useTableColumns, absoluteColumnWidth } from "./useTableColumns";
import type { TableProps, SortState } from "./types";
export function useTable(
  props: TableProps<any> & {
    defaultSelectedRowIds: string[];
    defaultSort: SortState | null;
    minColumnWidth: number;
    rowHeight: number;
    overscan: number;
    selectable: boolean;
  },
  emit: (name: any, ...args: any[]) => void,
) {
  const selected = useMotionState<string[]>(
      props,
      emit,
      "selectedRowIds",
      props.defaultSelectedRowIds,
    ),
    sort = useMotionState<SortState | null>(
      props,
      emit,
      "sort",
      props.defaultSort,
    );
  const headers = ref<Record<string, HTMLElement | null>>({}),
    rowElements = ref<Record<string, HTMLElement | null>>({}),
    viewport = ref<HTMLElement | null>(null),
    reduce = useReducedMotion(),
    rootFontSize = ref(16);
  const controller = useTableColumns(
      () => props.columns,
      headers,
      () => props.minColumnWidth,
      emit,
    ),
    columns = controller.ordered,
    widths = controller.widths;
  onMounted(() => {
    const measured = parseFloat(
      getComputedStyle(document.documentElement).fontSize,
    );
    if (measured > 0) rootFontSize.value = measured;
  });
  const rows = computed(() => {
    const entries = props.data.map((row, index) => ({
        row,
        id: props.getRowId?.(row, index) ?? String(index),
      })),
      sorting = sort.value;
    const column = sorting
      ? props.columns.find((column) => column.key === sorting.key)
      : undefined;
    if (!sorting || !column) return entries;
    const read = (row: any) =>
      column.sortValue ? column.sortValue(row) : row[column.key];
    return entries.sort((a, b) => {
      const first = read(a.row),
        second = read(b.row);
      return (
        (sorting.direction === "asc" ? 1 : -1) *
        (typeof first === "number" && typeof second === "number"
          ? first - second
          : String(first).localeCompare(String(second)))
      );
    });
  });
  const selectedSet = computed(() => new Set(selected.value)),
    allSelected = computed(
      () =>
        rows.value.length > 0 &&
        rows.value.every((entry) => selectedSet.value.has(entry.id)),
    ),
    someSelected = computed(() =>
      rows.value.some((entry) => selectedSet.value.has(entry.id)),
    );
  function select(ids: Set<string>) {
    const next = Array.from(ids);
    selected.value = next;
    emit("selectionChange", next);
  }
  function toggleAll() {
    const ids = new Set(selectedSet.value),
      remove = allSelected.value;
    for (const { id } of rows.value)
      if (remove) ids.delete(id);
      else ids.add(id);
    select(ids);
  }
  function toggleRow(id: string) {
    const ids = new Set(selectedSet.value);
    if (ids.has(id)) ids.delete(id);
    else ids.add(id);
    select(ids);
  }
  function toggleSort(key: string) {
    const current = sort.value,
      next =
        current?.key !== key
          ? { key, direction: "asc" as const }
          : current.direction === "asc"
            ? { key, direction: "desc" as const }
            : null;
    sort.value = next;
    emit("sortChange", next);
  }
  const virtualizer = useVirtualizer(
    computed(() => ({
      count: rows.value.length,
      getScrollElement: () => viewport.value,
      estimateSize: () => props.rowHeight,
      overscan: props.overscan,
      getItemKey: (index: number) => rows.value[index]?.id ?? index,
    })),
  );
  // A filtered data set can render before the virtualizer receives its new count.
  const virtualRows = computed(() =>
      virtualizer.value
        .getVirtualItems()
        .filter((item) => item.index < rows.value.length),
    ),
    total = computed(() => virtualizer.value.getTotalSize()),
    paddingTop = computed(() => virtualRows.value[0]?.start ?? 0),
    paddingBottom = computed(() =>
      virtualRows.value.length
        ? total.value - virtualRows.value.at(-1)!.end
        : 0,
    );
  const sized = computed(
    () =>
      columns.value.length > 0 &&
      columns.value.every((column) => widths.value[column.key] != null),
  );
  const minWidth = computed(() =>
    Math.round(
      columns.value.reduce(
        (sum, column) =>
          sum +
          (widths.value[column.key] ??
            absoluteColumnWidth(column.width, rootFontSize.value) ??
            (props.onColumnRename || (!column.cell && column.editable)
              ? Math.max(props.minColumnWidth, 120)
              : props.minColumnWidth)),
        props.selectable ? 48 : 0,
      ),
    ),
  );
  const colSpan = computed(
    () => columns.value.length + (props.selectable ? 1 : 0) + 1,
  );
  let reached = false;
  watch(
    () => props.loading,
    (loading) => {
      if (!loading) reached = false;
    },
